from editB import d
# ---- Ch28
d.cutp('She accepted the answer without trying to turn it into gallantry.')
d.after('Perrott signed the dispatch register at ten twenty-eight.','''What nobody in the office knew was that Bell’s secretary had paid the regular courier on Tuesday. He got as far as the corner of the street before a man in a blue coat took the bag out of his hands, and the courier, who was a person of principle in matters touching his wages, shouted for a constable and was ignored.''')
d.cutp('At ten thirty, three certified duplicates were beyond Bell’s sole control.','''At ten thirty, two certified duplicates were beyond Bell’s reach. One was with Gant’s apprentice at the solicitor’s door. The other had gone down a back lane in a bucket boy’s fist and into the hands of the Foreign Office under-secretary named on Perrott’s list, who signed for it in his dressing gown without being asked what it was. The two copies agreed. Two agreeing copies in separate hands was all the register required. The third, which Bell had in his pocket by twenty-nine minutes past, was only paper.''')

# ---- voice: the distinction tic
d.sub('The young man considered the distinction. “Will anyone read it?”','The young man considered this. “Will anyone read it?”')
d.sub('Saye did not appreciate the distinction. He gestured','Saye did not appreciate the point. He gestured')
d.sub('I would like the arrangement to acknowledge the distinction.”','I would like the arrangement to remember which is which.”')
d.sub('The distinction seemed to reach Saye with unusual force.','That seemed to reach Saye with unusual force.')
d.sub('Arthur wrote the distinction down.','Arthur wrote it down.')
d.sub('“He had me killed. There’s a distinction.”\n\n“Not one you’ll enjoy.”','“He had me killed.”\n\n“Somebody shot him on Bell’s say-so,” Miriam said. “That’s what killed means, Arthur.”')
d.sub('“The courts may not appreciate the distinction.”\n\n“Then we’ll make it clear.”','“The magistrates may not see the difference.”\n\n“Then we’ll make it plain.”')
d.sub('“An important distinction,” he said.','“Thank you for the accuracy, Miss Crumb,” he said.')
d.sub('Ives asked that the distinction between the two living Bells be included in every question.','Ives asked that every question say which Bell was meant.')
d.sub('“Yes. I’m trying to distinguish them.”','“Yes. I’m trying to work out the proportions.”')
d.sub('He considered the distinction and stepped onto the pavement.','He considered this and stepped onto the pavement.')
d.sub('The distinction would probably irritate clients for years.','It would probably irritate clients for years.')
